        assert!(media_types.contains(&MediaType::ScreenShare));
    }

    #[test]
    fn test_call_quality_metrics() {
        // Test good quality detection
        let good_metrics = CallQualityMetrics {
            rtt_ms: 50,
            packet_loss_percent: 0.5,
            jitter_ms: 15,
