use crate::messaging::types::{RichMessage, MessageSignature};
use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EncryptionManager {
    keys: HashMap<String, Vec<u8>>,
    signatures: HashMap<String, MessageSignature>,
}

impl EncryptionManager {
    pub fn new() -> Self {
        Self {
            keys: HashMap::new(),
            signatures: HashMap::new(),
        }
    }

    pub async fn encrypt_message(&mut self, message: &RichMessage, key_id: &str) -> Result<Vec<u8>> {
        let key = self.keys.get(key_id)
            .ok_or_else(|| anyhow::anyhow!("Encryption key not found"))?;

        // Simple XOR encryption for demonstration
        let message_bytes = serde_json::to_vec(message)?;
        let encrypted = self.xor_encrypt(&message_bytes, key);

        Ok(encrypted)
    }

    pub async fn decrypt_message(&self, encrypted_data: &[u8], key_id: &str) -> Result<RichMessage> {
        let key = self.keys.get(key_id)
            .ok_or_else(|| anyhow::anyhow!("Decryption key not found"))?;

        let decrypted = self.xor_decrypt(encrypted_data, key);
        let message: RichMessage = serde_json::from_slice(&decrypted)?;

        Ok(message)
    }

    pub async fn sign_message(&mut self, message: &RichMessage, key_id: &str) -> Result<MessageSignature> {
        // Simple signature implementation
        let message_bytes = serde_json::to_vec(message)?;
        let signature_data = self.compute_signature(&message_bytes, key_id)?;

        let signature = MessageSignature {
            algorithm: "simple_hash".to_string(),
            signature: signature_data,
            public_key: self.keys.get(key_id).unwrap_or(&Vec::new()).clone(),
        };

        Ok(signature)
    }

    pub async fn verify_signature(&self, message: &RichMessage, signature: &MessageSignature) -> Result<bool> {
        let message_bytes = serde_json::to_vec(message)?;
        let expected_signature = self.compute_signature_with_key(&message_bytes, &signature.public_key)?;

        Ok(signature.signature == expected_signature)
    }

    pub async fn generate_key(&mut self, key_id: String) -> Result<()> {
        let mut key = vec![0u8; 32];
        use rand::RngCore;
        rand::thread_rng().fill_bytes(&mut key);

        self.keys.insert(key_id, key);
        Ok(())
    }

    pub async fn import_key(&mut self, key_id: String, key_data: Vec<u8>) -> Result<()> {
        self.keys.insert(key_id, key_data);
        Ok(())
    }

    pub fn has_key(&self, key_id: &str) -> bool {
        self.keys.contains_key(key_id)
    }

    fn xor_encrypt(&self, data: &[u8], key: &[u8]) -> Vec<u8> {
        data.iter()
            .enumerate()
            .map(|(i, byte)| byte ^ key[i % key.len()])
            .collect()
    }

    fn xor_decrypt(&self, data: &[u8], key: &[u8]) -> Vec<u8> {
        // XOR decryption is the same as encryption
        self.xor_encrypt(data, key)
    }

    fn compute_signature(&self, data: &[u8], key_id: &str) -> Result<Vec<u8>> {
        if let Some(key) = self.keys.get(key_id) {
            self.compute_signature_with_key(data, key)
        } else {
            Err(anyhow::anyhow!("Signing key not found"))
        }
    }

    fn compute_signature_with_key(&self, data: &[u8], key: &[u8]) -> Result<Vec<u8>> {
        // Simple hash-based signature
        use std::collections::hash_map::DefaultHasher;
        use std::hash::{Hash, Hasher};

        let mut hasher = DefaultHasher::new();
        data.hash(&mut hasher);
        key.hash(&mut hasher);

        let hash = hasher.finish();
        Ok(hash.to_le_bytes().to_vec())
    }
}

