        Ok(())
    }

    pub async fn search(&self, query: &str) -> Result<Vec<&RichMessage>> {
        let query_words: Vec<String> = self.extract_words(query)
            .into_iter()
            .map(|s| s.to_lowercase())
            .collect();

        if query_words.is_empty() {
            return Ok(Vec::new());
        }

        // Find messages that contain all query words
        let mut matching_message_ids: Option<HashSet<String>> = None;

        for word in query_words {
            if let Some(message_ids) = self.word_to_messages.get(&word) {
                match &matching_message_ids {
                    None => matching_message_ids = Some(message_ids.clone()),
                    Some(existing) => {
                        let intersection: HashSet<String> = existing
                            .intersection(message_ids)
                            .cloned()
                            .collect();
                        matching_message_ids = Some(intersection);
                    }
                }
            } else {
                // If any word is not found, no messages match
                return Ok(Vec::new());
            }
        }

        // Collect matching messages
        let mut results = Vec::new();
        if let Some(message_ids) = matching_message_ids {
            for message_id in message_ids {
                if let Some(message) = self.message_content.get(&message_id) {
                    results.push(message);
                }
            }
        }

        Ok(results)
    }

    pub async fn remove_message(&mut self, message_id: &str) -> Result<bool> {
        if let Some(message) = self.message_content.remove(message_id) {
            // Remove from word index
            let words = self.extract_words(&message.text);
            for word in words {
                if let Some(message_set) = self.word_to_messages.get_mut(&word.to_lowercase()) {
                    message_set.remove(message_id);
                    if message_set.is_empty() {
                        self.word_to_messages.remove(&word.to_lowercase());
                    }
                }
            }

            // Remove metadata words
            for (key, value) in &message.metadata {
                let key_words = self.extract_words(key);
                let value_words = self.extract_words(value);

                for word in key_words.into_iter().chain(value_words) {
                    if let Some(message_set) = self.word_to_messages.get_mut(&word.to_lowercase()) {
                        message_set.remove(message_id);
                        if message_set.is_empty() {
                            self.word_to_messages.remove(&word.to_lowercase());
                        }
                    }
                }
            }

            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn extract_words(&self, text: &str) -> Vec<String> {
        text.split_whitespace()
            .map(|word| {
                word.chars()
                    .filter(|c| c.is_alphanumeric())
                    .collect::<String>()
            })
            .filter(|word| !word.is_empty())
            .collect()
    }
}

impl Default for SearchIndex {
    fn default() -> Self {
        Self::new()
    }
}
