use tokio::sync::mpsc;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TransportMessage {
    pub id: String,
    pub from: String,
    pub to: String,
    pub content: RichMessage,
    pub signature: Option<MessageSignature>,
    pub timestamp: u64,
}

#[derive(Debug)]
pub struct MessageTransport {
    peers: HashMap<String, mpsc::UnboundedSender<TransportMessage>>,
    receiver: mpsc::UnboundedReceiver<TransportMessage>,
    sender: mpsc::UnboundedSender<TransportMessage>,
}

impl MessageTransport {
    pub fn new() -> Self {
        let (sender, receiver) = mpsc::unbounded_channel();

        Self {
            peers: HashMap::new(),
            receiver,
            sender,
        }
    }

    pub async fn send_message(
        &mut self,
        to: String,
        message: RichMessage,
        signature: Option<MessageSignature>,
    ) -> Result<()> {
        let transport_message = TransportMessage {
            id: format!("msg_{}", uuid::Uuid::new_v4()),
            from: "local".to_string(), // In a real implementation, this would be the node ID
            to: to.clone(),
            content: message,
            signature,
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)?
                .as_secs(),
        };

        if let Some(peer_sender) = self.peers.get(&to) {
            peer_sender.send(transport_message)?;
        } else {
            // Store for later delivery or handle as needed
            self.sender.send(transport_message)?;
        }

        Ok(())
    }

    pub async fn receive_message(&mut self) -> Option<TransportMessage> {
        self.receiver.recv().await
    }

    pub fn add_peer(&mut self, peer_id: String, sender: mpsc::UnboundedSender<TransportMessage>) {
        self.peers.insert(peer_id, sender);
    }

    pub fn remove_peer(&mut self, peer_id: &str) {
        self.peers.remove(peer_id);
    }

    pub fn get_connected_peers(&self) -> Vec<String> {
        self.peers.keys().cloned().collect()
    }

    pub async fn broadcast_message(
        &mut self,
        message: RichMessage,
        signature: Option<MessageSignature>,
    ) -> Result<()> {
        let peers: Vec<String> = self.peers.keys().cloned().collect();

        for peer_id in peers {
            // Use Box::pin to handle async recursion
            Box::pin(self.send_message(peer_id, message.clone(), signature.clone())).await?;
        }

        Ok(())
    }

    pub fn is_connected_to(&self, peer_id: &str) -> bool {
        self.peers.contains_key(peer_id)
    }
}

impl Default for MessageTransport {
    fn default() -> Self {
        Self::new()
    }
}
