        let temp_dir = tempfile::tempdir().unwrap();
        let db_path = temp_dir.path().join("test.db").to_string_lossy().to_string();

        let dht = DhtClient::new_mock();
        let store = DatabaseMessageStore::new(dht, Some(db_path)).await.unwrap();

        // Create test message
