/// Message content types
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum MessageContent {
    /// Plain text message
    Text(String),

    /// Rich text with markdown formatting
    RichText(MarkdownContent),

    /// Code block with syntax highlighting
    Code(CodeBlock),

    /// Voice message
    Voice(VoiceMessage),

    /// Video message
    Video(VideoMessage),

    /// Location sharing
    Location(GeoLocation),

    /// Poll/survey
    Poll(PollMessage),

    /// System message (join, leave, etc.)
    System(SystemMessage),

    /// Sticker
    Sticker(Sticker),

    /// GIF
    Gif(GifMessage),
}

/// Markdown formatted content
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MarkdownContent {
    pub raw: String,
    pub formatted: String,
    pub mentions: Vec<FourWordAddress>,
    pub links: Vec<String>,
}

/// Code block with syntax highlighting
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CodeBlock {
    pub language: String,
    pub code: String,
    pub filename: Option<String>,
    pub line_numbers: bool,
}

/// Voice message
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VoiceMessage {
    pub duration_seconds: u32,
    pub waveform: Vec<u8>,
    pub transcription: Option<String>,
    pub mime_type: String,
    pub data: Vec<u8>,
}

/// Video message
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VideoMessage {
    pub duration_seconds: u32,
    pub thumbnail: Vec<u8>,
    pub width: u32,
    pub height: u32,
    pub mime_type: String,
    pub data: Vec<u8>,
}

/// Geographic location
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GeoLocation {
    pub latitude: f64,
    pub longitude: f64,
    pub accuracy_meters: Option<f32>,
    pub address: Option<String>,
    pub place_name: Option<String>,
}

/// Poll message
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PollMessage {
    pub question: String,
    pub options: Vec<PollOption>,
    pub allows_multiple: bool,
    pub anonymous: bool,
    pub closes_at: Option<DateTime<Utc>>,
}

/// Poll option
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PollOption {
    pub id: String,
    pub text: String,
    pub votes: Vec<FourWordAddress>,
}

/// System message types
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum SystemMessage {
    UserJoined(FourWordAddress),
    UserLeft(FourWordAddress),
    ChannelCreated,
    ChannelRenamed(String),
    UserInvited(FourWordAddress, FourWordAddress), // inviter, invitee
    CallStarted(FourWordAddress),
    CallEnded { duration_seconds: u32 },
    MessagePinned(MessageId),
}

/// Sticker message
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Sticker {
    pub pack_id: String,
    pub sticker_id: String,
    pub emoji: String,
    pub animated: bool,
    pub data: Vec<u8>,
}

/// GIF message
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GifMessage {
    pub url: String,
    pub thumbnail: Vec<u8>,
    pub width: u32,
    pub height: u32,
    pub caption: Option<String>,
}

/// File attachment
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Attachment {
    pub id: String,
    pub filename: String,
    pub mime_type: String,
    pub size_bytes: u64,
    pub thumbnail: Option<Vec<u8>>,
    pub dht_hash: String,
    pub encryption_key: Option<Vec<u8>>,
}

/// Encryption methods
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum EncryptionMethod {
    /// End-to-end encryption
    E2E,
    /// Transport layer security only
    TLS,
    /// No encryption (not recommended)
    None,
}

/// Message signature for verification
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct MessageSignature {
    pub algorithm: String,
    pub signature: Vec<u8>,
}

/// Encrypted message wrapper
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EncryptedMessage {
    pub id: MessageId,
    pub channel_id: ChannelId,
