        keys.insert(peer, established);

        Ok(encryption_key)
    }

    /// Get our prekey bundle for others to use
    pub async fn get_prekey_bundle(&self) -> PrekeyBundle {
        let prekeys = self.prekeys.read().await;
        prekeys.clone()
    }

