        // Generate identity key
        let identity_secret = EphemeralSecret::random_from_rng(OsRng);
        let identity_public = PublicKey::from(&identity_secret);

        // Generate signed prekey
        let signed_secret = EphemeralSecret::random_from_rng(OsRng);
        let signed_public = PublicKey::from(&signed_secret);

        // Sign the prekey
        let mut hasher = blake3::Hasher::new();
        hasher.update(signed_public.as_bytes());
        let signature = hasher.finalize().as_bytes().to_vec();

        let signed_prekey = SignedPrekey {
            id: rand::random(),
            public_key: signed_public.as_bytes().to_vec(),
            signature,
            timestamp: Utc::now(),
        };

        // Generate one-time prekeys
        let mut one_time_prekeys = Vec::new();
        for i in 0..100 {
            let secret = EphemeralSecret::random_from_rng(OsRng);
            let public = PublicKey::from(&secret);

            one_time_prekeys.push(OnetimePrekey {
