   244→            // 1. Use DHT to discover peer's current network endpoints
   245→            // 2. Initiate ant-quic connection with hole punching
   246→            // 3. Establish bidirectional QUIC streams for WebRTC media
   247→            
   248→            if self.quic_config.dht_discovery {
   249→                debug!("Using DHT discovery for peer {}", session.remote_peer);
   250→                // self.dht_client.find_peer(&session.remote_peer).await?;
   251→            }
   252→            
   253→            if self.quic_config.hole_punching {
   254→                debug!("Using coordinator-based hole punching for peer {}", session.remote_peer);
   255→                // Coordinator would facilitate NAT traversal using STUN-like probing
   256→                // but over native QUIC connection establishment
   257→            }
   258→            
   259→            debug!("QUIC connection established for call {}", call_id.0);
   260→        } else {
   261→            return Err(anyhow::anyhow!("No active session for call {}", call_id.0));
   262→        }
   263→        
   264→        Ok(())
   265→    }
   266→    
   267→    /// End a call
   268→    pub async fn end_call(&self, call_id: CallId) -> Result<()> {
   269→        let message = SignalingMessage::CallEnd { call_id };
   270→        
   271→        // Get session
   272→        let sessions = self.sessions.read().await;
   273→        if let Some(session) = sessions.get(&call_id) {
   274→            let remote_peer = session.remote_peer.clone();
   275→            drop(sessions);
   276→            
   277→            // Send end message
   278→            self.send_signaling_message(&remote_peer, message).await?;
   279→            
   280→            // Remove session
   281→            let mut sessions = self.sessions.write().await;
   282→            sessions.remove(&call_id);
   283→            
   284→            // Emit event
   285→            let _ = self.event_sender.send(SignalingEvent::CallEnded { call_id });
   286→            
   287→            info!("Ended call {}", call_id.0);
   288→        }
   289→        
   290→        Ok(())
   291→    }
   292→    
   293→    /// Reject a call
   294→    pub async fn reject_call(&self, call_id: CallId) -> Result<()> {
   295→        let message = SignalingMessage::CallReject { call_id };
   296→        
   297→        // Get session
   298→        let sessions = self.sessions.read().await;
   299→        if let Some(session) = sessions.get(&call_id) {
   300→            let remote_peer = session.remote_peer.clone();
   301→            drop(sessions);
   302→            
   303→            // Send reject message
   304→            self.send_signaling_message(&remote_peer, message).await?;
   305→            
   306→            // Update session state
   307→            let mut sessions = self.sessions.write().await;
   308→            if let Some(session) = sessions.get_mut(&call_id) {
   309→                session.state = SignalingState::Rejected;
   310→                session.last_activity = Utc::now();
   311→            }
   312→            
   313→            // Emit event
   314→            let _ = self.event_sender.send(SignalingEvent::CallRejected { call_id });
   315→            
   316→            info!("Rejected call {}", call_id.0);
   317→        }
   318→        
   319→        Ok(())
   320→    }
   321→    
   322→    /// Get signaling session
   323→    pub async fn get_session(&self, call_id: CallId) -> Option<SignalingSession> {
   324→        let sessions = self.sessions.read().await;
   325→        sessions.get(&call_id).cloned()
   326→    }
