   362→    /// Send signaling message via DHT
   363→    async fn send_signaling_message(&self, peer: &FourWordAddress, message: SignalingMessage) -> Result<()> {
   364→        // Create signaling envelope
   365→        let envelope = SignalingEnvelope {
   366→            sender: self.local_identity.clone(),
   367→            recipient: peer.clone(),
   368→            message,
   369→            timestamp: Utc::now(),
   370→            signature: self.sign_message(peer),
   371→        };
   372→        
   373→        // Serialize and send via DHT
   374→        let _data = serde_json::to_vec(&envelope)
   375→            .context("Failed to serialize signaling message")?;
   376→        
   377→        // Use DHT key based on recipient identity
   378→        let dht_key = format!("webrtc-signaling:{}", peer);
   379→        
   380→        // Store in DHT (this would be the actual DHT put operation)
   381→        debug!("Storing signaling message in DHT at key: {}", dht_key);
   382→        
   383→        // In production, we would:
   384→        // self.dht_client.put(dht_key, data).await?;
   385→        
   386→        Ok(())
   387→    }
   388→    
   389→    /// Handle incoming signaling message
   390→    async fn handle_incoming_message(&self, envelope: SignalingEnvelope) -> Result<()> {
   391→        // Verify message signature
   392→        if !self.verify_message_signature(&envelope) {
   393→            warn!("Invalid signature on signaling message from {}", envelope.sender);
   394→            return Ok(());
   395→        }
   396→        
   397→        // Process based on message type
   398→        match envelope.message {
   399→            SignalingMessage::Offer(offer) => {
   400→                self.handle_incoming_offer(offer).await?;
   401→            }
   402→            SignalingMessage::Answer(answer) => {
   403→                self.handle_incoming_answer(answer).await?;
   404→            }
   405→            SignalingMessage::CallEnd { call_id } => {
   406→                self.handle_call_end(call_id).await?;
   407→            }
   408→            SignalingMessage::CallReject { call_id } => {
   409→                self.handle_call_reject(call_id).await?;
   410→            }
   411→        }
   412→        
   413→        Ok(())
   414→    }
   415→    
   416→    /// Handle incoming call offer
   417→    async fn handle_incoming_offer(&self, offer: CallOffer) -> Result<()> {
   418→        // Validate incoming SDP
   419→        if let Err(e) = Self::validate_sdp(&offer.sdp) {
   420→            error!("Rejecting call offer due to invalid SDP: {}", e);
   421→            return Err(e);
   422→        }
   423→        
   424→        // Create session for incoming call
   425→        let session = SignalingSession {
   426→            call_id: offer.call_id,
   427→            local_peer: self.local_identity.clone(),
   428→            remote_peer: offer.caller.clone(),
   429→            state: SignalingState::OfferReceived,
   430→            offer: Some(offer.clone()),
   431→            answer: None,
   432→            created_at: Utc::now(),
   433→            last_activity: Utc::now(),
   434→        };
   435→        
   436→        // Store session
   437→        let mut sessions = self.sessions.write().await;
   438→        sessions.insert(offer.call_id, session);
   439→        
   440→        // Emit event
   441→        let _ = self.event_sender.send(SignalingEvent::IncomingCall { offer });
   442→        
   443→        Ok(())
   444→    }
   445→    
   446→    /// Handle incoming call answer
   447→    async fn handle_incoming_answer(&self, answer: CallAnswer) -> Result<()> {
   448→        // Validate incoming SDP (if call was accepted)
   449→        if answer.accepted {
   450→            if let Err(e) = Self::validate_sdp(&answer.sdp) {
   451→                error!("Rejecting call answer due to invalid SDP: {}", e);
   452→                return Err(e);
   453→            }
   454→        }
   455→        
   456→        // Update session
   457→        let mut sessions = self.sessions.write().await;
   458→        if let Some(session) = sessions.get_mut(&answer.call_id) {
   459→            session.answer = Some(answer.clone());
   460→            session.state = if answer.accepted {
   461→                SignalingState::AnswerReceived
   462→            } else {
   463→                SignalingState::Rejected
   464→            };
   465→            session.last_activity = Utc::now();
   466→            
   467→            // Emit event
   468→            let _ = self.event_sender.send(SignalingEvent::AnswerReceived { answer: answer.clone() });
   469→            
   470→            // Start QUIC connection establishment
   471→            if answer.accepted {
   472→                self.handle_quic_connection_establishment(answer.call_id).await?;
   473→            }
   474→        }
   475→        
   476→        Ok(())
   477→    }
   478→    
   479→    /// Handle QUIC connection establishment after answer is received
   480→    async fn handle_quic_connection_establishment(&self, call_id: CallId) -> Result<()> {
   481→        debug!("Establishing QUIC connection for call {}", call_id.0);
   482→        
   483→        // Update session state to indicate connection is being established
   484→        let mut sessions = self.sessions.write().await;
   485→        if let Some(session) = sessions.get_mut(&call_id) {
   486→            session.last_activity = Utc::now();
   487→            session.state = SignalingState::IceExchange; // Reusing this state for QUIC establishment
   488→            
   489→            // Emit connection event
   490→            let _ = self.event_sender.send(SignalingEvent::ConnectionEstablishing { call_id });
   491→        }
   492→        
   493→        Ok(())
   494→    }
   495→    
   496→    /// Handle call end
   497→    async fn handle_call_end(&self, call_id: CallId) -> Result<()> {
   498→        // Remove session
   499→        let mut sessions = self.sessions.write().await;
   500→        sessions.remove(&call_id);
   501→        
   502→        // Emit event
   503→        let _ = self.event_sender.send(SignalingEvent::CallEnded { call_id });
   504→        
   505→        Ok(())
   506→    }
   507→    
   508→    /// Handle call reject
   509→    async fn handle_call_reject(&self, call_id: CallId) -> Result<()> {
   510→        // Update session state
   511→        let mut sessions = self.sessions.write().await;
   512→        if let Some(session) = sessions.get_mut(&call_id) {
