   523→    /// Start cleanup task for expired sessions
   524→    async fn start_cleanup_task(&self) {
   525→        let sessions = Arc::clone(&self.sessions);
   526→        
   527→        tokio::spawn(async move {
   528→            let mut interval = tokio::time::interval(std::time::Duration::from_secs(60));
   529→            
   530→            loop {
   531→                interval.tick().await;
   532→                
   533→                let now = Utc::now();
   534→                let mut sessions = sessions.write().await;
   535→                let initial_count = sessions.len();
   536→                
   537→                // Remove sessions older than 10 minutes with no activity
   538→                sessions.retain(|_, session| {
   539→                    now.signed_duration_since(session.last_activity) < Duration::minutes(10)
   540→                });
   541→                
   542→                let removed = initial_count - sessions.len();
   543→                if removed > 0 {
