// Message type definitions for rich messaging

use crate::identity::FourWordAddress;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use chrono::{DateTime, Utc};
use uuid::Uuid;

/// Unique message identifier
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct MessageId(pub Uuid);

impl MessageId {
    pub fn new() -> Self {
        Self(Uuid::new_v4())
    }
}

impl std::fmt::Display for MessageId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

/// Thread identifier
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct ThreadId(pub Uuid);

impl ThreadId {
    pub fn new() -> Self {
        Self(Uuid::new_v4())
    }
}

/// Channel/conversation identifier  
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct ChannelId(pub Uuid);

impl ChannelId {
    pub fn new() -> Self {
        Self(Uuid::new_v4())
    }
}

impl std::fmt::Display for ChannelId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

/// Device identifier for multi-device support
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct DeviceId(pub String);

/// Rich message with all modern messaging features
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RichMessage {
    /// Unique message ID
    pub id: MessageId,

    /// Thread ID if part of a thread
    pub thread_id: Option<ThreadId>,

    /// Channel/conversation ID
    pub channel_id: ChannelId,

    /// Sender's four-word identity
    pub sender: FourWordAddress,

    /// Sender's device
    pub sender_device: DeviceId,

    /// Message content
    pub content: MessageContent,

    /// File attachments
    pub attachments: Vec<Attachment>,

    /// User mentions
    pub mentions: Vec<FourWordAddress>,

    /// Reply to another message
    pub reply_to: Option<MessageId>,

    /// Number of thread replies
    pub thread_count: u32,

    /// Last thread reply time
    pub last_thread_reply: Option<DateTime<Utc>>,

    /// Reactions grouped by emoji
    pub reactions: HashMap<String, Vec<FourWordAddress>>,

    /// Read receipts
    pub read_by: HashMap<FourWordAddress, DateTime<Utc>>,

    /// Delivery receipts
    pub delivered_to: HashMap<FourWordAddress, DateTime<Utc>>,

    /// Creation timestamp
    pub created_at: DateTime<Utc>,

    /// Edit timestamp
    pub edited_at: Option<DateTime<Utc>>,

    /// Deletion timestamp (soft delete)
    pub deleted_at: Option<DateTime<Utc>>,

    /// Message expiration for ephemeral messages
    pub expires_at: Option<DateTime<Utc>>,

    /// Whether this is an ephemeral message
    pub ephemeral: bool,

    /// Encryption method used
    pub encryption: EncryptionMethod,

    /// Message signature for verification
    pub signature: MessageSignature,
}

impl RichMessage {
    /// Create a new message
    pub fn new(
        sender: FourWordAddress,
        channel_id: ChannelId,
        content: MessageContent,
    ) -> Self {
        Self {
            id: MessageId::new(),
            thread_id: None,
            channel_id,
            sender,
            sender_device: DeviceId("primary".to_string()),
            content,
            attachments: Vec::new(),
            mentions: Vec::new(),
            reply_to: None,
            thread_count: 0,
            last_thread_reply: None,
            reactions: HashMap::new(),
            read_by: HashMap::new(),
            delivered_to: HashMap::new(),
            created_at: Utc::now(),
            edited_at: None,
            deleted_at: None,
            expires_at: None,
            ephemeral: false,
            encryption: EncryptionMethod::E2E,
            signature: MessageSignature::default(),
        }
    }

    /// Check if message is deleted
    pub fn is_deleted(&self) -> bool {
        self.deleted_at.is_some()
    }

    /// Check if message is edited
    pub fn is_edited(&self) -> bool {
        self.edited_at.is_some()
    }

    /// Check if message has expired
    pub fn is_expired(&self) -> bool {
        if let Some(expires_at) = self.expires_at {
            Utc::now() > expires_at
        } else {
            false
        }
    }
}

