        metrics.messages_sent = 100;
        metrics.messages_received = 95;
        metrics.packet_loss = 0.02;

        assert_eq!(metrics.messages_sent, 100);
        assert!(metrics.packet_loss < 0.05); // Less than 5% loss
    }
}

