// Rich Messaging Module for P2P Foundation
// Implements WhatsApp/Slack-style messaging with full decentralization

pub mod types;
pub mod composer;
pub mod threads;
pub mod reactions;
pub mod media;
pub mod search;
pub mod encryption;
pub mod key_exchange;
pub mod sync;
