        self.sync.broadcast_typing(channel_id, true).await
    }

    /// Stop typing indicator
    pub async fn stop_typing(&mut self, channel_id: ChannelId) -> Result<()> {
        self.sync.broadcast_typing(channel_id, false).await
    }

