        self.inner.search_messages(query, channel_id, 50).await
    }

    /// Get thread messages
    pub async fn get_thread_messages(&self, thread_id: ThreadId) -> Result<Vec<RichMessage>> {
        self.inner.get_thread_messages(thread_id).await
    }

    /// Add reaction
